"use strict";class Dropdown{constructor(e){this.button=e,this.closeOnClickOutsideBinded=this.closeOnClickOutside.bind(this),e.setAttribute("aria-expanded","false"),e.parentNode.addEventListener("mouseenter",this.open.bind(this)),e.parentNode.addEventListener("mouseleave",this.close.bind(this)),e.addEventListener("click",this.toggle.bind(this)),e.nextElementSibling.addEventListener("keydown",this.closeOnListKeydown.bind(this)),e.addEventListener("keydown",this.closeOnListKeydown.bind(this)),e.nextElementSibling.querySelector("li:last-child > a").addEventListener("blur",this.closeOnLastLinkBlur.bind(this))}open(){this.button.setAttribute("aria-expanded","true"),document.addEventListener("click",this.closeOnClickOutsideBinded)}close(){this.button.setAttribute("aria-expanded","false"),document.removeEventListener("click",this.closeOnClickOutsideBinded)}toggle(){this.button.getAttribute("aria-expanded")==="true"?this.close():this.open()}closeOnListKeydown(e){e.key==="Escape"&&(this.button.focus(),this.close())}closeOnLastLinkBlur(e){this.button.parentNode.contains(e.relatedTarget)||this.close()}closeOnClickOutside(e){this.button.parentNode.contains(e.target)||this.close()}}const lmatSwitcher={init:()=>{document.readyState!=="loading"?lmatSwitcher.ready():document.addEventListener("DOMContentLoaded",lmatSwitcher.ready)},ready:()=>{const s=document.getElementsByClassName("lmat-submenu-toggle");for(const t of s)new Dropdown(t);const e=document.getElementsByClassName("lmat-switcher-select");for(const t of e)t.addEventListener("change",n=>{n.currentTarget.value&&(window.location.href=n.currentTarget.value)})}};lmatSwitcher.init();
